  void Reader_array_f32(cityjobs_Reader& self, const List<U8>& b, List<Float>& v) {
    U32 n = 0;
    Reader_get_u32Result n13;
    n13 = Reader_get_u32(self, b);
    n = n13.Result;
    if (logic_or(logic_not(self.ok), math_compare<">">(kern::formula([](Int a, Int a_2) -> Float { return (a < 0.0) != (a_2 < 0.0) ? a_2 < 0.0 : a < a_2; }, value_int(kern::to<Int>(kern::formula([](Int a, Int p) -> Int { return a - p; }, list_length<U8>(b), self.p))), value_int(kern::to<Int>(kern::formula([](Int n) -> Int { return n * 4.0; }, n)))), 0.5))) {
      self.ok = false;
      return;
    }
    list_resize(v, n, 0.0);
    if (math_compare<"!=">(kern::to<Float>(n), 0.0)) {
      list_copy_bytes<"f32", "u8">(v, 0, b, self.p, kern::to<Int>(kern::formula([](Int n) -> Int { return n * 4.0; }, n)));
    }
    self.p = kern::to<Int>(kern::formula([](Int p, Int n) -> Int { return p + n * 4.0; }, self.p, n));
  }

